from typing import List

def search_mysterious_grid(phrases: List[str], grid: List[List[str]]) -> int:
    m, n = len(grid), len(grid[0])
    total = 0
    for p in phrases:
        L = len(p)
        found = set()  # 用格子序列去重：一条直线路径在不同“折返点”下会重复出现
        for i in range(m):
            for j in range(n):
                if grid[i][j] != p[0]:
                    continue
                for di, dj in ((0, 1), (1, 0)):          # 先向右 / 先向下
                    # t = 先沿初始方向走过的格子数（含起点）；t == L 表示不折返
                    for t in range(min(L, 2), L + 1):
                        cells, ci, cj, ok = [], i, j, True
                        for k in range(L):
                            if not (0 <= ci < m and 0 <= cj < n) or grid[ci][cj] != p[k]:
                                ok = False
                                break
                            cells.append((ci, cj))
                            s = 1 if k + 1 < t else -1   # 走满 t 格后掉头
                            ci, cj = ci + s * di, cj + s * dj
                        if ok:
                            found.add(tuple(cells))
        total += len(found)
    return total

if __name__ == "__main__":
    phrases = ["ac", "cat", "car", "bar", "acdc", "abacaba"]
    grid = [["a", "b", "a", "c"], ["x", "a", "c", "d"], ["y", "r", "d", "s"]]
    assert search_mysterious_grid(phrases, grid) == 7
    print("ok")
